    fn decode_vec_i64_output(bytes: &[u8]) -> Vec<i64> {
        let count = u32::from_le_bytes(bytes[0..4].try_into().unwrap()) as usize;
        (0..count)
            .map(|idx| {
                let off = 4 + idx * 8;
                i64::from_le_bytes(bytes[off..off + 8].try_into().unwrap())
            })
            .collect()
    }
    fn repo_file(path: &str) -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(path)
    }
    fn strip_line_comments(text: &str) -> String {
        let mut out = String::new();
        for line in text.lines() {
            out.push_str(line.split("//").next().unwrap_or(""));
            out.push('\n');
        }
        out
    }
    #[test]
    fn interop_audit_forbids_external_runtime_dependencies_and_shellouts() {
        let manifest_paths = [
            repo_file("Cargo.toml"),
            repo_file("Cargo.lock"),
            repo_file("examples/ingen_native_front/Cargo.toml"),
            repo_file("examples/ingen_native_services/Cargo.toml"),
        ];
        let banned_deps = ["wasmtime", "wasmer", "llvm-sys", "inkwell", "mlir"];
        for path in &manifest_paths {
            let text = fs::read_to_string(path)
                .unwrap_or_else(|error| panic!("failed to read {}: {error}", path.display()));
            for raw_line in text.lines() {
                let line = raw_line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }
                for dep in banned_deps {
                    let quoted_name = format!("name = \"{dep}\"");
                    let direct_dep = format!("{dep} =");
                    if line == quoted_name || line.starts_with(&direct_dep) {
                        panic!("interop audit: banned external runtime dependency `{dep}` found in {}", path.display());
                    }
                }
                if line == "name = \"cranelift\"" || line.starts_with("cranelift-") || line.starts_with("cranelift =") {
                    panic!(
                        "interop audit: banned external runtime dependency `cranelift*` found in {}",
                        path.display()
                    );
                }
            }
        }
        let kasm_source = fs::read_to_string(repo_file("src/kasm.rs")).expect("read src/kasm.rs");
        let non_test_source = kasm_source
            .split("#[cfg(test)]")
            .next()
            .expect("kasm source before tests");
        let uncommented = strip_line_comments(non_test_source);
        for forbidden in ["Command::new", "std::process::Command", "tokio::process::Command", "mlir-opt"] {
            assert!(
                !uncommented.contains(forbidden),
                "interop audit: forbidden shell/runtime token `{forbidden}` present in src/kasm.rs"
            );
        }
    }
