        let xpz1 = b.imul(xpz, one); // x*1 ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ x
        let twelve = b.iadd(f1, f2); // 5+7 ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ 12 (const fold)
        let r = b.iadd(xpz1, twelve);
