#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum ForgeScalarTy {
    Bool,
    I32,
    I64,
    U32,
    U64,
    F32,
    F64,
}

impl ForgeScalarTy {
    pub fn parse(raw: &str) -> Option<Self> {
        Some(match raw.trim() {
            "bool" | "i1" => Self::Bool,
            "i32" => Self::I32,
            "i64" => Self::I64,
            "u32" => Self::U32,
            "u64" => Self::U64,
            "f32" => Self::F32,
            "f64" => Self::F64,
            _ => return None,
        })
    }

    pub fn name(self) -> &'static str {
        match self {
            Self::Bool => "bool",
            Self::I32 => "i32",
            Self::I64 => "i64",
            Self::U32 => "u32",
            Self::U64 => "u64",
            Self::F32 => "f32",
            Self::F64 => "f64",
        }
    }

    pub fn bytecode_ty(self) -> Ty {
        match self {
            Self::Bool => Ty::Bool,
            Self::I32 | Self::I64 | Self::U32 | Self::U64 => Ty::I64,
            Self::F32 | Self::F64 => Ty::F64,
        }
    }

    pub fn is_numeric(self) -> bool {
        !matches!(self, Self::Bool)
    }

    pub fn is_float(self) -> bool {
        matches!(self, Self::F32 | Self::F64)
    }

    pub fn is_integer(self) -> bool {
        matches!(self, Self::I32 | Self::I64 | Self::U32 | Self::U64)
    }

    pub fn promote_numeric(lhs: Self, rhs: Self) -> Option<Self> {
        if !lhs.is_numeric() || !rhs.is_numeric() {
            return None;
        }
        Some(if matches!(lhs, Self::F64) || matches!(rhs, Self::F64) {
            Self::F64
        } else if matches!(lhs, Self::F32) || matches!(rhs, Self::F32) {
            Self::F32
        } else if matches!((lhs, rhs), (Self::U64, Self::U64) | (Self::U64, Self::U32) | (Self::U32, Self::U64)) {
            Self::U64
        } else if matches!((lhs, rhs), (Self::U32, Self::U32)) {
            Self::U32
        } else if matches!(lhs, Self::I64 | Self::U64) || matches!(rhs, Self::I64 | Self::U64) {
            Self::I64
        } else if matches!(lhs, Self::I32) || matches!(rhs, Self::I32) {
            Self::I32
        } else {
            Self::U32
        })
    }
}

impl fmt::Display for ForgeScalarTy {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.name())
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum ForgeScalarValue {
    Bool(bool),
    I32(i32),
    I64(i64),
    U32(u32),
    U64(u64),
    F32(f32),
    F64(f64),
}

impl ForgeScalarValue {
    pub fn ty(self) -> ForgeScalarTy {
        match self {
            Self::Bool(_) => ForgeScalarTy::Bool,
            Self::I32(_) => ForgeScalarTy::I32,
            Self::I64(_) => ForgeScalarTy::I64,
            Self::U32(_) => ForgeScalarTy::U32,
            Self::U64(_) => ForgeScalarTy::U64,
            Self::F32(_) => ForgeScalarTy::F32,
            Self::F64(_) => ForgeScalarTy::F64,
        }
    }

    fn parse_number(raw: &str) -> Option<Self> {
        let text = raw.replace('_', "");
        let (number, suffix) = split_numeric_suffix(&text);
        if number.is_empty() || number == "." {
            return None;
        }
        let is_float_text = number.contains('.') || number.contains('e') || number.contains('E');
        match suffix {
            Some("i32") => number.parse::<i32>().ok().map(Self::I32),
            Some("i64") => number.parse::<i64>().ok().map(Self::I64),
            Some("u32") => number.parse::<u32>().ok().map(Self::U32),
            Some("u64") => number.parse::<u64>().ok().map(Self::U64),
            Some("f32") => {
                let value = number.parse::<f32>().ok()?;
                value.is_finite().then_some(Self::F32(value))
            }
            Some("f64") => {
                let value = number.parse::<f64>().ok()?;
                value.is_finite().then_some(Self::F64(value))
            }
            None if is_float_text => {
                let value = number.parse::<f64>().ok()?;
                value.is_finite().then_some(Self::F64(value))
            }
            None => number.parse::<i64>().ok().map(Self::I64),
            Some(_) => None,
        }
    }
}

impl fmt::Display for ForgeScalarValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Bool(value) => write!(f, "{value}"),
            Self::I32(value) => write!(f, "{value}i32"),
            Self::I64(value) => write!(f, "{value}i64"),
            Self::U32(value) => write!(f, "{value}u32"),
            Self::U64(value) => write!(f, "{value}u64"),
            Self::F32(value) => write!(f, "{value}f32"),
            Self::F64(value) => write!(f, "{value}f64"),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ForgeBounds {
    pub min: f64,
    pub max: f64,
}

impl ForgeBounds {
    pub fn new(min: f64, max: f64) -> Option<Self> {
        (min.is_finite() && max.is_finite() && min <= max).then_some(Self { min, max })
    }

    pub fn point(value: f64) -> Option<Self> {
        Self::new(value, value)
    }

    pub fn from_scalar(value: ForgeScalarValue) -> Option<Self> {
        match value {
            ForgeScalarValue::Bool(_) => None,
            ForgeScalarValue::I32(value) => Self::point(value as f64),
            ForgeScalarValue::I64(value) => Self::point(value as f64),
            ForgeScalarValue::U32(value) => Self::point(value as f64),
            ForgeScalarValue::U64(value) => Self::point(value as f64),
            ForgeScalarValue::F32(value) => Self::point(value as f64),
            ForgeScalarValue::F64(value) => Self::point(value),
        }
    }

    pub fn add(self, rhs: Self) -> Option<Self> {
        Self::new(self.min + rhs.min, self.max + rhs.max)
    }

    pub fn sub(self, rhs: Self) -> Option<Self> {
        Self::new(self.min - rhs.max, self.max - rhs.min)
    }

    pub fn neg(self) -> Option<Self> {
        Self::new(-self.max, -self.min)
    }

    pub fn mul(self, rhs: Self) -> Option<Self> {
        let values = [
            self.min * rhs.min,
            self.min * rhs.max,
            self.max * rhs.min,
            self.max * rhs.max,
        ];
        Self::from_values(values)
    }

    pub fn div(self, rhs: Self) -> Option<Self> {
        if rhs.contains_zero() {
            return None;
        }
        self.mul(Self::new(1.0 / rhs.max, 1.0 / rhs.min)?)
    }

    pub fn sqrt(self) -> Option<Self> {
        (self.min >= 0.0).then(|| Self::new(self.min.sqrt(), self.max.sqrt()))?
    }

    pub fn ln(self) -> Option<Self> {
        (self.min > 0.0).then(|| Self::new(self.min.ln(), self.max.ln()))?
    }

    pub fn exp(self) -> Option<Self> {
        Self::new(self.min.exp(), self.max.exp())
    }

    pub fn abs(self) -> Option<Self> {
        if self.min <= 0.0 && self.max >= 0.0 {
            Self::new(0.0, self.min.abs().max(self.max.abs()))
        } else {
            Self::new(self.min.abs().min(self.max.abs()), self.min.abs().max(self.max.abs()))
        }
    }

    pub fn min_bounds(self, rhs: Self) -> Option<Self> {
        Self::new(self.min.min(rhs.min), self.max.min(rhs.max))
    }

    pub fn max_bounds(self, rhs: Self) -> Option<Self> {
        Self::new(self.min.max(rhs.min), self.max.max(rhs.max))
    }

    pub fn clamp(self, lo: Self, hi: Self) -> Option<Self> {
        if lo.min > hi.max {
            return None;
        }
        Self::new(self.min.max(lo.min).min(hi.max), self.max.max(lo.min).min(hi.max))
    }

    pub fn powi(self, exp: i8) -> Option<Self> {
        let a = self.min.powi(exp as i32);
        let b = self.max.powi(exp as i32);
        if exp % 2 == 0 && self.contains_zero() {
            Self::new(0.0, a.abs().max(b.abs()))
        } else {
            Self::new(a.min(b), a.max(b))
        }
    }

    pub fn powf(self, exp: f64) -> Option<Self> {
        if !exp.is_finite() || self.min < 0.0 || (self.contains_zero() && exp < 0.0) {
            return None;
        }
        let a = self.min.powf(exp);
        let b = self.max.powf(exp);
        Self::new(a.min(b), a.max(b))
    }

    pub fn square(self) -> Option<Self> {
        let a = self.min * self.min;
        let b = self.max * self.max;
        if self.contains_zero() {
            Self::new(0.0, a.max(b))
        } else {
            Self::new(a.min(b), a.max(b))
        }
    }

    pub fn contains_zero(self) -> bool {
        self.min <= 0.0 && self.max >= 0.0
    }

    fn from_values(values: [f64; 4]) -> Option<Self> {
        let mut min = f64::INFINITY;
        let mut max = f64::NEG_INFINITY;
        for value in values {
            if !value.is_finite() {
                return None;
            }
            min = min.min(value);
            max = max.max(value);
        }
        Self::new(min, max)
    }
}

