    #[test]
    fn forge_expr_parser_preserves_precedence_calls_and_boolean_logic() {
        let expr = ForgeExpr::parse(
            "thrust - mass * g + pow(radius, 2) >= 0 && finite(thrust)",
        )
        .unwrap();
        assert_eq!(expr.calls(), vec!["finite".to_string(), "pow".to_string()]);
        assert_eq!(
            expr.variables(),
            vec![
                "g".to_string(),
                "mass".to_string(),
                "radius".to_string(),
                "thrust".to_string(),
            ]
        );
        assert!(matches!(expr, ForgeExpr::Binary { op: ForgeBinaryOp::And, .. }));
        assert!(ForgeExpr::parse("mass * (g + drag").is_none());
        assert!(ForgeExpr::parse("mass + ;").is_none());
    }

    #[test]
    fn forge_scalar_literals_parse_suffixes_and_infer_types() {
        assert_eq!(ForgeScalarValue::parse_number("12i32").unwrap().ty(), ForgeScalarTy::I32);
        assert_eq!(ForgeScalarValue::parse_number("12u64").unwrap().ty(), ForgeScalarTy::U64);
        assert_eq!(ForgeScalarValue::parse_number("1.25f32").unwrap().ty(), ForgeScalarTy::F32);
        assert_eq!(ForgeScalarValue::parse_number("1.25").unwrap().ty(), ForgeScalarTy::F64);
        assert_eq!(ForgeScalarValue::parse_number("12").unwrap().ty(), ForgeScalarTy::I64);
        assert!(ForgeScalarValue::parse_number("12usize").is_none());

        let vars = vec![("mass".to_string(), ForgeScalarTy::F64)];
        let funcs = Vec::new();
        assert_eq!(
            ForgeExpr::parse("mass + 2i32").unwrap().infer_scalar_ty(&vars, &funcs),
            Some(ForgeScalarTy::F64)
        );
        assert_eq!(
            ForgeExpr::parse("finite(mass) && true").unwrap().infer_scalar_ty(&vars, &funcs),
            Some(ForgeScalarTy::Bool)
        );
        assert!(ForgeExpr::parse("true + mass").unwrap().infer_scalar_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_vector_matrix_and_complex_exprs_infer_shapes() {
        let vars = vec![
            ("a".to_string(), ForgeType::Vec { elem: ForgeScalarTy::F32, lanes: 3 }),
            ("b".to_string(), ForgeType::Vec { elem: ForgeScalarTy::F32, lanes: 3 }),
            ("m".to_string(), ForgeType::Mat { elem: ForgeScalarTy::F32, cols: 3, rows: 3 }),
            ("z".to_string(), ForgeType::Complex { elem: ForgeScalarTy::F64 }),
        ];
        let funcs = Vec::new();
        assert_eq!(
            ForgeExpr::parse("vec3(1.0f32, 2.0f32, 3.0f32)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Vec { elem: ForgeScalarTy::F32, lanes: 3 })
        );
        assert_eq!(
            ForgeExpr::parse("dot(a, b)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F32))
        );
        assert_eq!(
            ForgeExpr::parse("cross(a, b) + normalize(a)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Vec { elem: ForgeScalarTy::F32, lanes: 3 })
        );
        assert_eq!(
            ForgeExpr::parse("m * a").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Vec { elem: ForgeScalarTy::F32, lanes: 3 })
        );
        assert_eq!(
            ForgeExpr::parse("complex(1.0, 2.0) * z").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Complex { elem: ForgeScalarTy::F64 })
        );
        assert!(ForgeExpr::parse("cross(vec2(1.0f32, 2.0f32), a)").unwrap().infer_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_collection_exprs_infer_shapes_and_elements() {
        let vars = vec![
            ("samples".to_string(), ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 }),
            ("field3".to_string(), ForgeType::Field { elem: ForgeScalarTy::F32, rank: 3 }),
            ("ticks".to_string(), ForgeType::Column { elem: ForgeScalarTy::F64 }),
            (
                "book".to_string(),
                ForgeType::Table {
                    columns: vec![
                        ("price".to_string(), ForgeScalarTy::F64),
                        ("volume".to_string(), ForgeScalarTy::I64),
                    ],
                },
            ),
            ("g".to_string(), ForgeType::Graph { node: ForgeScalarTy::U64, edge: ForgeScalarTy::F32 }),
        ];
        let funcs = Vec::new();
        assert_eq!(
            ForgeExpr::parse("len(samples)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::U64))
        );
        assert_eq!(
            ForgeExpr::parse("shape(samples)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::U64, len: 1 })
        );
        assert_eq!(
            ForgeExpr::parse("index(samples, 2u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F64))
        );
        assert_eq!(
            ForgeExpr::parse("sum(ticks)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F64))
        );
        assert_eq!(
            ForgeExpr::parse("sample(field3, vec3(0.0f32, 1.0f32, 2.0f32))").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F32))
        );
        assert_eq!(
            ForgeExpr::parse("rows(book) + cols(book)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::U64))
        );
        assert_eq!(
            ForgeExpr::parse("node_count(g) + edge_count(g)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::U64))
        );
        assert!(ForgeExpr::parse("index(samples, 1.5f32)").unwrap().infer_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_data_parallel_combinators_infer_collection_shapes() {
        let vars = vec![
            ("samples".to_string(), ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 }),
            ("other".to_string(), ForgeType::Array { elem: ForgeScalarTy::F32, len: 8 }),
            ("idx".to_string(), ForgeType::Array { elem: ForgeScalarTy::U64, len: 4 }),
        ];
        let funcs = vec![
            (
                "square".to_string(),
                vec![ForgeType::Scalar(ForgeScalarTy::F64)],
                ForgeType::Scalar(ForgeScalarTy::F64),
            ),
            (
                "accum".to_string(),
                vec![ForgeType::Scalar(ForgeScalarTy::F64), ForgeType::Scalar(ForgeScalarTy::F64)],
                ForgeType::Scalar(ForgeScalarTy::F64),
            ),
            (
                "positive".to_string(),
                vec![ForgeType::Scalar(ForgeScalarTy::F64)],
                ForgeType::Scalar(ForgeScalarTy::Bool),
            ),
        ];
        assert_eq!(
            ForgeExpr::parse("map(square, samples)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 })
        );
        assert_eq!(
            ForgeExpr::parse("reduce(accum, 0.0, samples)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F64))
        );
        assert_eq!(
            ForgeExpr::parse("scan(accum, 0.0, samples)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 })
        );
        assert_eq!(
            ForgeExpr::parse("filter(positive, samples)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Column { elem: ForgeScalarTy::F64 })
        );
        assert_eq!(
            ForgeExpr::parse("zip(samples, other)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Table {
                columns: vec![
                    ("left".to_string(), ForgeScalarTy::F64),
                    ("right".to_string(), ForgeScalarTy::F32),
                ],
            })
        );
        assert_eq!(
            ForgeExpr::parse("gather(samples, idx)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 4 })
        );
        assert_eq!(
            ForgeExpr::parse("scatter(samples, idx, gather(samples, idx))").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 })
        );
        assert!(ForgeExpr::parse("filter(square, samples)").unwrap().infer_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_query_time_ops_infer_windows_and_joins() {
        let ticks_ty = ForgeType::Table {
            columns: vec![
                ("time".to_string(), ForgeScalarTy::U64),
                ("price".to_string(), ForgeScalarTy::F64),
                ("volume".to_string(), ForgeScalarTy::I64),
            ],
        };
        let quotes_ty = ForgeType::Table {
            columns: vec![
                ("time".to_string(), ForgeScalarTy::U64),
                ("bid".to_string(), ForgeScalarTy::F64),
            ],
        };
        let vars = vec![
            ("prices".to_string(), ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 }),
            ("ticks".to_string(), ticks_ty.clone()),
            ("quotes".to_string(), quotes_ty),
        ];
        let funcs = vec![(
            "avg3".to_string(),
            vec![ForgeType::Array { elem: ForgeScalarTy::F64, len: 3 }],
            ForgeType::Scalar(ForgeScalarTy::F64),
        )];
        assert_eq!(
            ForgeExpr::parse("window(prices, 3u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F64, shape: vec![6, 3] })
        );
        assert_eq!(
            ForgeExpr::parse("rolling(avg3, 3u64, prices)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 6 })
        );
        assert_eq!(
            ForgeExpr::parse("groupby(ticks, 0u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ticks_ty.clone())
        );
        assert_eq!(
            ForgeExpr::parse("asof_join(ticks, quotes, 0u64, 0u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Table {
                columns: vec![
                    ("time".to_string(), ForgeScalarTy::U64),
                    ("price".to_string(), ForgeScalarTy::F64),
                    ("volume".to_string(), ForgeScalarTy::I64),
                    ("right_time".to_string(), ForgeScalarTy::U64),
                    ("right_bid".to_string(), ForgeScalarTy::F64),
                ],
            })
        );
        assert!(ForgeExpr::parse("window(prices, 99u64)").unwrap().infer_ty(&vars, &funcs).is_none());
        assert!(ForgeExpr::parse("asof_join(ticks, quotes, 1u64, 0u64)").unwrap().infer_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_sampling_ops_infer_deterministic_designs() {
        let vars = Vec::new();
        let funcs = vec![(
            "score".to_string(),
            vec![ForgeType::Array { elem: ForgeScalarTy::F64, len: 2 }],
            ForgeType::Scalar(ForgeScalarTy::F64),
        )];
        assert_eq!(
            ForgeExpr::parse("sobol(2u64, 8u64, 42u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F64, shape: vec![8, 2] })
        );
        assert_eq!(
            ForgeExpr::parse("latin_hypercube(2u64, 8u64, 42u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F64, shape: vec![8, 2] })
        );
        assert_eq!(
            ForgeExpr::parse("monte_carlo(score, sobol(2u64, 8u64, 42u64), 42u64)")
                .unwrap()
                .infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F64))
        );
        assert!(ForgeExpr::parse("sobol(0u64, 8u64, 42u64)").unwrap().infer_ty(&vars, &funcs).is_none());
        assert!(ForgeExpr::parse("monte_carlo(score, latin_hypercube(3u64, 8u64, 42u64))")
            .unwrap()
            .infer_ty(&vars, &funcs)
            .is_none());
    }

    #[test]
    fn forge_selection_ops_infer_rank_topk_pareto_and_diversity() {
        let vars = vec![
            ("scores".to_string(), ForgeType::Array { elem: ForgeScalarTy::F64, len: 8 }),
            ("points".to_string(), ForgeType::Tensor { elem: ForgeScalarTy::F64, shape: vec![8, 3] }),
            ("matrix".to_string(), ForgeType::Mat { elem: ForgeScalarTy::F64, cols: 4, rows: 4 }),
        ];
        let funcs = Vec::new();
        assert_eq!(
            ForgeExpr::parse("rank(scores)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::U64, len: 8 })
        );
        assert_eq!(
            ForgeExpr::parse("top_k(scores, 3u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 3 })
        );
        assert_eq!(
            ForgeExpr::parse("pareto(points)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::U64, len: 8 })
        );
        assert_eq!(
            ForgeExpr::parse("diversity_select(points, 4u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F64, shape: vec![4, 3] })
        );
        assert_eq!(
            ForgeExpr::parse("top_k(flatten(matrix), 4u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Array { elem: ForgeScalarTy::F64, len: 4 })
        );
        assert!(ForgeExpr::parse("top_k(scores, 9u64)").unwrap().infer_ty(&vars, &funcs).is_none());
        assert!(ForgeExpr::parse("pareto(scores)").unwrap().infer_ty(&vars, &funcs).is_none());
        assert!(ForgeExpr::parse("diversity_select(points, 9u64)").unwrap().infer_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_signal_transforms_infer_complex_spectrum_shapes() {
        let vars = vec![
            ("signal".to_string(), ForgeType::Array { elem: ForgeScalarTy::F32, len: 8 }),
            ("bad_signal".to_string(), ForgeType::Array { elem: ForgeScalarTy::F32, len: 7 }),
            ("spectrum".to_string(), ForgeType::Tensor { elem: ForgeScalarTy::F32, shape: vec![8, 2] }),
        ];
        let funcs = Vec::new();

        assert_eq!(
            ForgeExpr::parse("fft(signal)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F32, shape: vec![8, 2] })
        );
        assert_eq!(
            ForgeExpr::parse("rfft(signal)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F32, shape: vec![5, 2] })
        );
        assert_eq!(
            ForgeExpr::parse("ifft(spectrum)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Tensor { elem: ForgeScalarTy::F32, shape: vec![8, 2] })
        );
        assert!(ForgeExpr::parse("fft(bad_signal)").unwrap().infer_ty(&vars, &funcs).is_none());
    }

    #[test]
    fn forge_module_accepts_selection_source_pipeline() {
        let source = r#"
forge_module:
  module selection_compute version 1
forge_constants:
  none
forge_functions:
  fn identity(x: f64) -> f64 { return x }
forge_program:
  let ranked = rank(scores)
  let best = top_k(scores, 3u64)
  let fronts = pareto(points)
  let diverse = diversity_select(points, 4u64)
  let best_total_value = identity(sum(best))
  emit best_total: f64 = best_total_value
  emit front_total: u64 = sum(fronts)
  emit diverse_total: f64 = sum(diverse)
forge_inputs:
  param scores: array<f64,8> unit none bounds [0.0, 100.0] nominal 50.0
  param points: tensor<f64,8x3> unit none bounds [0.0, 1.0] nominal 0.5
forge_outputs:
  output best_total: f64 unit none handoff scalar
  output front_total: u64 unit none handoff scalar
  output diverse_total: f64 unit none handoff scalar
forge_constraints:
  assert finite(best_total)
  assert finite(front_total)
  assert finite(diverse_total)
forge_samples:
  case smoke { given scores=1.0, points=0.5; expect best_total approx 3.0 tolerance 3.0 }
forge_cost:
  max_steps=10000
  max_memory_mb=2
  precision=f64
artifact_handoff:
  proof_hash,output_hash,compact_result
"#;
        assert!(ForgeModuleSpec::parse(source).is_some());
        let too_many = source.replace("top_k(scores, 3u64)", "top_k(scores, 9u64)");
        assert!(ForgeModuleSpec::parse(&too_many).is_none());
    }

