    #[test]
    fn forge_bounds_reject_zero_division_and_invalid_domains() {
        let div_zero = r#"
forge_module:
  module bad_div version 1
forge_constants:
  none
forge_functions:
  fn bad(force: f64, area: f64) -> f64 { return force / area }
forge_program:
  let pressure = bad(force, area)
  emit pressure_out: f64 = pressure
forge_inputs:
  param force: f64 unit N bounds [1.0, 100.0] nominal 10.0
  param area: f64 unit m^2 bounds [-1.0, 1.0] nominal 0.5
forge_outputs:
  output pressure_out: f64 unit Pa handoff scalar
forge_constraints:
  assert finite(pressure_out)
forge_samples:
  case bad { given force=10.0, area=0.5; expect pressure_out approx 20.0 tolerance 0.01 }
forge_cost:
  max_steps=1000
  max_memory_mb=4
  precision=f64
artifact_handoff:
  proof_hash,output_hash,compact_result
"#;
        assert!(ForgeModuleSpec::parse(div_zero).is_none());

        let bad_sqrt = div_zero
            .replace("module bad_div", "module bad_sqrt")
            .replace("fn bad(force: f64, area: f64) -> f64 { return force / area }", "fn bad(force: f64, area: f64) -> f64 { return sqrt(area) }")
            .replace("output pressure_out: f64 unit Pa handoff scalar", "output pressure_out: f64 unit m handoff scalar");
        assert!(ForgeModuleSpec::parse(&bad_sqrt).is_none());

        let bad_log = div_zero
            .replace("module bad_div", "module bad_log")
            .replace("fn bad(force: f64, area: f64) -> f64 { return force / area }", "fn bad(force: f64, area: f64) -> f64 { return log(area) }")
            .replace("output pressure_out: f64 unit Pa handoff scalar", "output pressure_out: f64 unit none handoff scalar");
        assert!(ForgeModuleSpec::parse(&bad_log).is_none());
    }

    #[test]
    fn forge_output_spec_parses_type_unit_and_handoff() {
        let output = ForgeOutputSpec::parse(
            "output chamber_pressure: f64 unit Pa handoff scalar",
        )
        .unwrap();
        assert_eq!(output.name, "chamber_pressure");
        assert_eq!(output.bytecode_ty(), Some(Ty::F64));
        assert_eq!(output.unit_dim(), ForgeUnitDim::parse("N/m^2"));
        assert_eq!(output.handoff, ForgeOutputKind::Scalar);
        assert_eq!(ForgeOutputKind::parse("table"), Some(ForgeOutputKind::Table));
        assert_eq!(ForgeOutputKind::parse("graph"), Some(ForgeOutputKind::Graph));
        assert_eq!(ForgeOutputKind::parse("timeseries"), Some(ForgeOutputKind::Timeseries));
        assert_eq!(ForgeOutputKind::parse("artifact"), Some(ForgeOutputKind::Artifact));
        assert!(
            ForgeOutputSpec::parse(
                "output ticks: table<time:u64;price:f64> unit none handoff timeseries"
            )
            .is_some()
        );
        assert!(ForgeOutputSpec::parse("output broken: f64 unit mystery handoff scalar").is_none());
    }

    #[test]
    fn forge_const_function_program_and_handoff_parse() {
        let constant = ForgeConstSpec::parse("const g: f64 unit m/s^2 = 9.80665").unwrap();
        assert_eq!(constant.name, "g");
        assert_eq!(constant.const_hash_hex().len(), 64);
        let function = ForgeFunctionSpec::parse(
            "fn margin(mass: f64, thrust: f64) -> f64 { return thrust - mass * 9.80665 }",
        )
        .unwrap();
        assert_eq!(function.args.len(), 2);
        assert_eq!(function.function_hash_hex().len(), 64);
        let program = ForgeProgramSpec::parse(
            "let margin_value = margin(mass, thrust)\nemit thrust_margin: f64 = margin_value",
        )
        .unwrap();
        assert_eq!(program.lets.len(), 1);
        assert_eq!(program.emits[0].name, "thrust_margin");
        let handoff = ForgeArtifactHandoff::parse("proof_hash,output_hash,compact_result").unwrap();
        assert!(handoff.items.iter().any(|item| item == "proof_hash"));
    }

