    fn forge_import_hash_parses_and_canonicalizes() {
        let import = ForgeImportSpec::parse(
            "import hash aero = SHA256:0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF",
        )
        .unwrap();
        assert_eq!(import.name, "aero");
        assert_eq!(
            import.hash,
            "sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
        );
        assert_eq!(import.import_hash_hex().len(), 64);
        assert!(ForgeImportSpec::parse("import hash bad = nope").is_none());
    }

    #[test]
    fn forge_source_purity_rejects_effectful_calls() {
        assert!(ForgeFunctionSpec::parse("fn bad() -> f64 { return random() }").is_none());
        assert!(ForgeFunctionSpec::parse("fn bad() -> f64 { return read_file(secret_path) }").is_none());
        assert!(ForgeConstraintSpec::parse("assert now() > 0").is_none());
        let expr = ForgeExpr::parse("sqrt(x) + abs(y)").unwrap();
        assert!(expr.is_pure_source());
    }

    #[test]
    fn forge_source_accepts_only_bounded_loop_forms() {
        let funcs = vec![
            (
                "step".to_string(),
                vec![
                    ForgeType::Scalar(ForgeScalarTy::I64),
                    ForgeType::Scalar(ForgeScalarTy::F64),
                ],
                ForgeType::Scalar(ForgeScalarTy::F64),
            ),
            (
                "cond".to_string(),
                vec![ForgeType::Scalar(ForgeScalarTy::I64)],
                ForgeType::Scalar(ForgeScalarTy::Bool),
            ),
            (
                "body".to_string(),
                vec![ForgeType::Scalar(ForgeScalarTy::I64)],
                ForgeType::Scalar(ForgeScalarTy::I64),
            ),
        ];
        let vars = Vec::new();
        assert_eq!(
            ForgeExpr::parse("fori(step, 0i64, 10i64, 1.0)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::F64))
        );
        assert_eq!(
            ForgeExpr::parse("while_fuel(cond, body, 3i64, 32u64)").unwrap().infer_ty(&vars, &funcs),
            Some(ForgeType::Scalar(ForgeScalarTy::I64))
        );
        assert!(ForgeFunctionSpec::parse("fn bad(x: f64) -> f64 { return while(x) }").is_none());
        assert!(ForgeFunctionSpec::parse("fn fori(x: f64) -> f64 { return x }").is_none());
    }

