        assert_eq!(hashes.source_hash.len(), 64);
        assert_eq!(hashes.imports_hash.len(), 64);
        assert_eq!(hashes.constants_hash.len(), 64);
        assert_eq!(hashes.functions_hash.len(), 64);
        assert_eq!(hashes.fragment_hash.len(), 64);
        assert_eq!(hashes.input_hash.len(), 64);
        assert_eq!(hashes.output_hash.len(), 64);
        assert_eq!(hashes.type_hash.len(), 64);
        assert_eq!(hashes.unit_hash.len(), 64);
        assert_eq!(hashes.bounds_hash.len(), 64);
        assert_eq!(hashes.contract_hash.len(), 64);
        assert_eq!(hashes.proof_hash.len(), 64);

        let changed = source.replace(
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
        );
        let changed = ForgeModuleSpec::parse(&changed).unwrap();
