    #[test]
    fn forge_module_lowers_to_typed_compute_ir_with_parallel_ops() {
        let source = r#"
forge_module:
  module ir_demo version 1
forge_constants:
  const bias: f64 unit none = 1.0f64
forge_functions:
  fn square(x: f64) -> f64 { return x * x + bias }
  fn add(acc: f64, x: f64) -> f64 { return acc + x }
forge_program:
  let ys = map(square, samples)
  let total_value = reduce(add, 0.0f64, ys)
  emit total: f64 = total_value
forge_inputs:
  param samples: array<f64,8> unit none bounds [0.0, 10.0] nominal 1.0
forge_outputs:
  output total: f64 unit none handoff scalar
forge_constraints:
  assert finite(total)
forge_samples:
  case basic seed 1 { given samples=1.0; expect total approx 16.0 tolerance 0.01 }
forge_cost:
  max_steps=10000
  max_memory_mb=16
  precision=f64
  parallelism=8
artifact_handoff:
  proof_hash,output_hash
"#;
        let spec = ForgeModuleSpec::parse(source).unwrap();
        let ir = spec.lower_to_compute_ir().unwrap();
        assert_eq!(ir.schema, "forge.compute_ir.module.v1");
        assert_eq!(ir.module_name, "ir_demo");
        assert_eq!(ir.ir_hash.len(), 64);
        assert_eq!(ir.outputs.len(), 1);
        assert!(ir.nodes.iter().any(|node| matches!(node.kernel_class, crate::kasm::types::ForgeIrKernelClass::Elementwise)));
        assert!(ir.nodes.iter().any(|node| matches!(node.kernel_class, crate::kasm::types::ForgeIrKernelClass::Reduction)));
        assert!(ir
            .nodes
            .iter()
            .any(|node| matches!(&node.op, crate::kasm::types::ForgeIrOp::Call { name } if name == "map:square")));
        assert!(ir
            .nodes
            .iter()
            .any(|node| matches!(&node.op, crate::kasm::types::ForgeIrOp::Call { name } if name == "reduce:add")));
        assert!(ir.buffers.iter().any(|buffer| buffer.name == "samples" && buffer.role == "input"));
        assert!(ir.buffers.iter().any(|buffer| buffer.name == "total" && buffer.role == "output"));
    }

