#[derive(Clone, Debug, PartialEq)]
pub struct ForgeOutputSpec {
    pub name: String,
    pub ty: ForgeType,
    pub unit: String,
    pub handoff: ForgeOutputKind,
}

impl ForgeOutputSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let raw = raw.trim();
        let rest = raw.strip_prefix("output ")?;
        let (name, rest) = rest.split_once(':')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let (ty_text, rest) = rest.trim().split_once(" unit ")?;
        let ty = ForgeType::parse(ty_text)?;
        let (unit, handoff) = rest.trim().split_once(" handoff ")?;
        let unit = unit.trim();
        if ForgeUnitDim::parse(unit).is_none() {
            return None;
        }
        Some(Self {
            name: name.to_string(),
            ty,
            unit: unit.to_string(),
            handoff: ForgeOutputKind::parse(handoff.trim())?,
        })
    }

    pub fn bytecode_ty(&self) -> Option<Ty> {
        self.ty.bytecode_ty()
    }

    pub fn unit_dim(&self) -> Option<ForgeUnitDim> {
        ForgeUnitDim::parse(&self.unit)
    }

    pub fn canonical_source(&self) -> String {
        format!(
            "output {}: {} unit {} handoff {}",
            self.name, self.ty, self.unit, self.handoff
        )
    }

    pub fn output_hash_hex(&self) -> String {
        hash_text_hex("forge.source.output.v1", &self.canonical_source())
    }

}

