#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ForgeCostSpec {
    pub max_steps: u64,
    pub max_memory_mb: u64,
    pub precision: ForgePrecision,
    pub parallelism: Option<u32>,
    pub min_estimated_ops: Option<u64>,
}

impl ForgeCostSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let mut max_steps = None;
        let mut max_memory_mb = None;
        let mut precision = None;
        let mut parallelism = None;
        let mut min_estimated_ops = None;
        for line in raw.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let (key, value) = line.split_once('=')?;
            match key.trim() {
                "max_steps" => max_steps = value.trim().parse::<u64>().ok(),
                "max_memory_mb" => max_memory_mb = value.trim().parse::<u64>().ok(),
                "precision" => precision = ForgePrecision::parse(value.trim()),
                "parallelism" => parallelism = Some(value.trim().parse::<u32>().ok()?),
                "min_estimated_ops" => min_estimated_ops = Some(value.trim().parse::<u64>().ok()?),
                _ => return None,
            }
        }
        let spec = Self {
            max_steps: max_steps?,
            max_memory_mb: max_memory_mb?,
            precision: precision?,
            parallelism,
            min_estimated_ops,
        };
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        self.max_steps > 0
            && self.max_memory_mb > 0
            && self.parallelism.unwrap_or(1) > 0
            && self.parallelism.unwrap_or(1) <= 4096
            && self.min_estimated_ops.unwrap_or(1) > 0
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum ForgeConstraintSpec {
    Finite { value: String },
    Bounds { value: String, min: f64, max: f64 },
    Approx { actual: String, expected: String, tolerance: f64 },
    Assert { expr: String },
}

impl ForgeConstraintSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let raw = raw.trim();
        let expr = raw.strip_prefix("assert ")?.trim();
        if let Some(inner) = expr.strip_prefix("finite(").and_then(|value| value.strip_suffix(')')) {
            let value = inner.trim();
            if valid_forge_expr_text(value) {
                return Some(Self::Finite { value: value.to_string() });
            }
            return None;
        }
        if let Some(inner) = expr.strip_prefix("bounds(").and_then(|value| value.strip_suffix(')')) {
            let parts = split_top_level_commas(inner);
            if parts.len() != 2 {
                return None;
            }
            let value = parts[0].trim();
            let bounds = parts[1].trim();
            let bounds = bounds.strip_prefix('[')?.strip_suffix(']')?;
            let (min, max) = bounds.split_once(',')?;
            let min = min.trim().parse::<f64>().ok()?;
            let max = max.trim().parse::<f64>().ok()?;
            if valid_forge_expr_text(value) && min.is_finite() && max.is_finite() && min <= max {
                return Some(Self::Bounds { value: value.to_string(), min, max });
            }
            return None;
        }
        if let Some(inner) = expr.strip_prefix("approx(").and_then(|value| value.strip_suffix(')')) {
            let parts = split_top_level_commas(inner);
            if parts.len() != 3 {
                return None;
            }
            let actual = parts[0].trim();
            let expected = parts[1].trim();
            let tolerance = parts[2].trim().parse::<f64>().ok()?;
            if valid_forge_expr_text(actual)
                && valid_forge_expr_text(expected)
                && tolerance.is_finite()
                && tolerance >= 0.0
            {
                return Some(Self::Approx {
                    actual: actual.to_string(),
                    expected: expected.to_string(),
                    tolerance,
                });
            }
            return None;
        }
        if Self::valid_expr(expr) {
            Some(Self::Assert { expr: expr.to_string() })
        } else {
            None
        }
    }

    fn valid_expr(expr: &str) -> bool {
        valid_forge_expr_text(expr)
    }

    pub fn canonical_source(&self) -> String {
        match self {
            Self::Finite { value } => format!("assert finite({value})"),
            Self::Bounds { value, min, max } => {
                format!("assert bounds({value},[{min},{max}])")
            }
            Self::Approx { actual, expected, tolerance } => {
                format!("assert approx({actual},{expected},{tolerance})")
            }
            Self::Assert { expr } => format!("assert {expr}"),
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ForgeSampleCase {
    pub name: String,
    pub seed: Option<u64>,
    pub givens: Vec<(String, f64)>,
    pub expect_output: String,
    pub expect_value: f64,
    pub tolerance: f64,
}

impl ForgeSampleCase {
    pub fn parse(raw: &str) -> Option<Self> {
        let raw = raw.trim();
        let rest = raw.strip_prefix("case ")?;
        let (header, body) = rest.split_once('{')?;
        let (name, seed) = parse_sample_case_header(header.trim())?;
        if !is_forge_ident(name) {
            return None;
        }
        let body = body.strip_suffix('}')?.trim();
        let mut givens = None;
        let mut expect = None;
        for part in body.split(';') {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            if let Some(raw_givens) = part.strip_prefix("given ") {
                let parsed = raw_givens
                    .split(',')
                    .map(|item| {
                        let (key, value) = item.trim().split_once('=')?;
                        let key = key.trim();
                        if !is_forge_ident(key) {
                            return None;
                        }
                        Some((key.to_string(), value.trim().parse::<f64>().ok()?))
                    })
                    .collect::<Option<Vec<_>>>()?;
                givens = Some(parsed);
            } else if let Some(raw_expect) = part.strip_prefix("expect ") {
                let (output, rest) = raw_expect.split_once(" approx ")?;
                let output = output.trim();
                if !is_forge_ident(output) {
                    return None;
                }
                let (value, tolerance) = rest.split_once(" tolerance ")?;
                expect = Some((
                    output.to_string(),
                    value.trim().parse::<f64>().ok()?,
                    tolerance.trim().parse::<f64>().ok()?,
                ));
            } else {
                return None;
            }
        }
        let givens = givens?;
        let (expect_output, expect_value, tolerance) = expect?;
        let case = Self {
            name: name.to_string(),
            seed,
            givens,
            expect_output,
            expect_value,
            tolerance,
        };
        case.is_valid().then_some(case)
    }

    pub fn is_valid(&self) -> bool {
        !self.givens.is_empty()
            && !has_duplicates(&self.givens.iter().map(|(name, _)| name.as_str()).collect::<Vec<_>>())
            && self.givens.iter().all(|(_, value)| value.is_finite())
            && self.expect_value.is_finite()
            && self.tolerance.is_finite()
            && self.tolerance >= 0.0
    }

    pub fn canonical_source(&self) -> String {
        let givens = self
            .givens
            .iter()
            .map(|(name, value)| format!("{name}={value}"))
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "case {} seed {} {{ given {}; expect {} approx {} tolerance {} }}",
            self.name,
            self.seed.unwrap_or(0),
            givens,
            self.expect_output,
            self.expect_value,
            self.tolerance
        )
    }

    pub fn sample_hash_hex(&self) -> String {
        hash_text_hex("forge.source.sample.v1", &self.canonical_source())
    }
}

fn parse_sample_case_header(header: &str) -> Option<(&str, Option<u64>)> {
    if let Some((name, seed)) = header.split_once(" seed ") {
        let seed = seed.trim().parse::<u64>().ok()?;
        Some((name.trim(), Some(seed)))
    } else {
        Some((header.trim(), None))
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ForgeConstSpec {
    pub name: String,
    pub ty: ForgeType,
    pub unit: String,
    pub value: ForgeScalarValue,
}

impl ForgeConstSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("const ")?;
        let (name, rest) = rest.split_once(':')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let (ty_text, rest) = rest.trim().split_once(" unit ")?;
        let ty = ForgeType::parse(ty_text)?;
        let (unit, value) = rest.trim().split_once('=')?;
        let unit = unit.trim();
        if ForgeUnitDim::parse(unit).is_none() {
            return None;
        }
        let value = ForgeScalarValue::parse_number(value.trim())?;
        Some(Self {
            name: name.to_string(),
            ty,
            unit: unit.to_string(),
            value,
        })
        .filter(Self::is_valid)
    }

    pub fn is_valid(&self) -> bool {
        self.ty
            .scalar_ty()
            .map(|ty| scalar_assignable(self.value.ty(), ty))
            .unwrap_or(false)
    }

    pub fn unit_dim(&self) -> Option<ForgeUnitDim> {
        ForgeUnitDim::parse(&self.unit)
    }

    pub fn canonical_source(&self) -> String {
        format!("const {}: {} unit {} = {}", self.name, self.ty, self.unit, self.value)
    }

    pub fn const_hash_hex(&self) -> String {
        hash_text_hex("forge.source.const.v1", &self.canonical_source())
    }
}

