#[derive(Clone, Debug, PartialEq)]
pub struct ForgeFunctionSpec {
    pub name: String,
    pub args: Vec<ForgeFunctionArg>,
    pub result_ty: ForgeType,
    pub body: String,
}

impl ForgeFunctionSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("fn ")?;
        let (name, rest) = rest.split_once('(')?;
        let name = name.trim();
        if !is_forge_ident(name) || is_reserved_forge_control_ident(name) {
            return None;
        }
        let (args, rest) = rest.split_once(')')?;
        let args = if args.trim().is_empty() {
            Vec::new()
        } else {
            split_top_level_commas(args)
                .into_iter()
                .map(ForgeFunctionArg::parse)
                .collect::<Option<Vec<_>>>()?
        };
        let rest = rest.trim().strip_prefix("->")?.trim();
        let (result_ty, body) = rest.split_once('{')?;
        let body = body.strip_suffix('}')?.trim();
        let spec = Self {
            name: name.to_string(),
            args,
            result_ty: ForgeType::parse(result_ty.trim())?,
            body: body.to_string(),
        };
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        let Some(expr) = forge_function_return_expr(&self.body) else {
            return false;
        };
        !self.body.is_empty()
            && self.body.len() <= 4096
            && !self.body.chars().any(|ch| ch.is_control() && ch != '\n' && ch != '\t')
            && !has_duplicates(&self.args.iter().map(|arg| arg.name.as_str()).collect::<Vec<_>>())
            && ForgeExpr::parse(expr)
                .map(|expr| expr.is_pure_source() && expr.has_only_bounded_control_source())
                .unwrap_or(false)
    }

    pub fn canonical_source(&self) -> String {
        let args = self
            .args
            .iter()
            .map(|arg| format!("{}: {}", arg.name, arg.ty))
            .collect::<Vec<_>>()
            .join(",");
        format!("fn {}({}) -> {} {{ {} }}", self.name, args, self.result_ty, self.body)
    }

    pub fn function_hash_hex(&self) -> String {
        hash_text_hex("forge.source.function.v1", &self.canonical_source())
    }
}

