#[derive(Clone, Debug, PartialEq)]
pub struct ForgeProgramSpec {
    pub lets: Vec<ForgeProgramLet>,
    pub emits: Vec<ForgeProgramEmit>,
}

impl ForgeProgramSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let mut lets = Vec::new();
        let mut emits = Vec::new();
        for line in raw.lines().map(str::trim).filter(|line| !line.is_empty() && !line.starts_with('#')) {
            if let Some(rest) = line.strip_prefix("let ") {
                let (name, expr) = rest.split_once('=')?;
                let name = name.trim();
                if !is_forge_ident(name) {
                    return None;
                }
                let expr = expr.trim();
                if !valid_forge_expr_text(expr) {
                    return None;
                }
                lets.push(ForgeProgramLet { name: name.to_string(), expr: expr.to_string() });
            } else if let Some(rest) = line.strip_prefix("emit ") {
                let (name, rest) = rest.split_once(':')?;
                let name = name.trim();
                if !is_forge_ident(name) {
                    return None;
                }
                let (ty, expr) = rest.trim().split_once('=')?;
                let expr = expr.trim();
                if !valid_forge_expr_text(expr) {
                    return None;
                }
                emits.push(ForgeProgramEmit {
                    name: name.to_string(),
                    ty: ForgeType::parse(ty.trim())?,
                    expr: expr.to_string(),
                });
            } else {
                return None;
            }
        }
        let spec = Self { lets, emits };
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        !self.emits.is_empty()
            && !has_duplicates(&self.lets.iter().map(|item| item.name.as_str()).collect::<Vec<_>>())
            && !has_duplicates(&self.emits.iter().map(|item| item.name.as_str()).collect::<Vec<_>>())
    }

    pub fn canonical_source(&self) -> String {
        let mut out = String::new();
        for item in &self.lets {
            out.push_str(&item.canonical_source());
            out.push('\n');
        }
        for item in &self.emits {
            out.push_str(&item.canonical_source());
            out.push('\n');
        }
        out
    }

    pub fn fragment_hash_hex(&self) -> String {
        hash_text_hex("forge.source.fragments.v1", &self.canonical_source())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ForgeArtifactHandoff {
    pub items: Vec<String>,
}

impl ForgeArtifactHandoff {
    pub fn parse(raw: &str) -> Option<Self> {
        let raw = raw.trim();
        let raw = raw.strip_prefix("artifact_handoff=").unwrap_or(raw);
        let items = raw
            .split(',')
            .map(str::trim)
            .filter(|item| !item.is_empty())
            .map(|item| is_forge_ident(item).then_some(item.to_string()))
            .collect::<Option<Vec<_>>>()?;
        let spec = Self { items };
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        self.items.iter().any(|item| item == "proof_hash")
            && self.items.iter().any(|item| item == "output_hash")
            && !has_duplicates(&self.items.iter().map(String::as_str).collect::<Vec<_>>())
    }
}

