#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ForgeScheduleSpec {
    pub name: String,
    pub target: String,
    pub algorithm: String,
    pub tile: u32,
    pub vectorize: u32,
    pub gpu: bool,
    pub layout: ForgeScheduleLayout,
}

impl ForgeScheduleSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("schedule ")?;
        let (name, body) = rest.split_once(':')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let mut target = None;
        let mut algorithm = None;
        let mut tile = None;
        let mut vectorize = None;
        let mut gpu = None;
        let mut layout = None;
        for item in body.split_whitespace() {
            let (key, value) = item.split_once('=')?;
            match key {
                "target" => {
                    if !is_forge_ident(value) {
                        return None;
                    }
                    target = Some(value.to_string());
                }
                "algorithm" => {
                    if !is_forge_ident(value) {
                        return None;
                    }
                    algorithm = Some(value.to_string());
                }
                "tile" => tile = Some(value.parse::<u32>().ok()?.clamp(1, 4096)),
                "vectorize" => vectorize = Some(value.parse::<u32>().ok()?.clamp(1, 1024)),
                "gpu" => gpu = Some(match value {
                    "true" => true,
                    "false" => false,
                    _ => return None,
                }),
                "layout" => layout = Some(ForgeScheduleLayout::parse(value)?),
                _ => return None,
            }
        }
        Some(Self {
            name: name.to_string(),
            target: target?,
            algorithm: algorithm?,
            tile: tile.unwrap_or(1),
            vectorize: vectorize.unwrap_or(1),
            gpu: gpu.unwrap_or(false),
            layout: layout?,
        })
    }

    pub fn canonical_source(&self) -> String {
        format!(
            "schedule {}: target={} algorithm={} tile={} vectorize={} gpu={} layout={}",
            self.name,
            self.target,
            self.algorithm,
            self.tile,
            self.vectorize,
            self.gpu,
            self.layout.name()
        )
    }
}

/// Declarative metamorphic / property relations a Forge module promises about an
/// emitted output. These let a LLM state invariants that must hold across the
/// whole bounded input domain, not just the one or two `forge_samples` cases.
///
/// The kinds follow the classical metamorphic-relation taxonomy from
/// property-based and metamorphic testing (symmetry, idempotence, involution,
/// monotonicity, homogeneity, translation, permutation invariance, range and
/// conservation). `finite` and `range` are statically verified against the
/// existing bounds inference; the structural metamorphic relations are sealed
/// into the language/IR/Monster contract so the runtime property plan can later
/// enforce them. The backend never invents these relations: the LLM chooses
/// them, Forge only types, hashes and forwards them.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum ForgePropertyKind {
    Finite,
    Range,
    MonotoneIncreasing,
    MonotoneDecreasing,
    Even,
    Odd,
    Idempotent,
    Involutive,
    ScaleInvariant,
    Homogeneous,
    Translation,
    PermutationInvariant,
    Conserves,
}

impl ForgePropertyKind {
    pub fn parse(raw: &str) -> Option<Self> {
        Some(match raw.trim() {
            "finite" => Self::Finite,
            "range" => Self::Range,
            "monotone_increasing" => Self::MonotoneIncreasing,
            "monotone_decreasing" => Self::MonotoneDecreasing,
            "even" => Self::Even,
            "odd" => Self::Odd,
            "idempotent" => Self::Idempotent,
            "involutive" => Self::Involutive,
            "scale_invariant" => Self::ScaleInvariant,
            "homogeneous" => Self::Homogeneous,
            "translation" => Self::Translation,
            "permutation_invariant" => Self::PermutationInvariant,
            "conserves" => Self::Conserves,
            _ => return None,
        })
    }

    pub fn name(self) -> &'static str {
        match self {
            Self::Finite => "finite",
            Self::Range => "range",
            Self::MonotoneIncreasing => "monotone_increasing",
            Self::MonotoneDecreasing => "monotone_decreasing",
            Self::Even => "even",
            Self::Odd => "odd",
            Self::Idempotent => "idempotent",
            Self::Involutive => "involutive",
            Self::ScaleInvariant => "scale_invariant",
            Self::Homogeneous => "homogeneous",
            Self::Translation => "translation",
            Self::PermutationInvariant => "permutation_invariant",
            Self::Conserves => "conserves",
        }
    }

    /// `(named_params, numeric_args)` arity expected after the target argument.
    pub fn signature(self) -> (usize, usize) {
        match self {
            Self::Finite | Self::Idempotent | Self::Involutive => (0, 0),
            Self::Range => (0, 2),
            Self::MonotoneIncreasing
            | Self::MonotoneDecreasing
            | Self::Even
            | Self::Odd
            | Self::ScaleInvariant
            | Self::PermutationInvariant
            | Self::Conserves => (1, 0),
            Self::Homogeneous | Self::Translation => (1, 1),
        }
    }

    /// Whether Forge can discharge this relation statically with bounds
    /// inference. The remaining relations are sealed for the Monster property
    /// plan to enforce at run time.
    pub fn is_static(self) -> bool {
        matches!(self, Self::Finite | Self::Range)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ForgePropertySpec {
    pub name: String,
    pub kind: ForgePropertyKind,
    pub target: String,
    pub params: Vec<String>,
    pub numeric_args: Vec<f64>,
    pub tolerance: f64,
}

impl ForgePropertySpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("property ")?;
        let (name, body) = rest.split_once(':')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let (call, tolerance) = body.trim().split_once(" tolerance ")?;
        let tolerance = tolerance.trim().parse::<f64>().ok()?;
        let call = call.trim().replace(' ', "");
        let (kind, args) = call.split_once('(')?;
        let args = args.strip_suffix(')')?;
        let kind = ForgePropertyKind::parse(kind)?;
        let mut tokens = args.split(',').map(str::trim).filter(|tok| !tok.is_empty());
        let target = tokens.next()?.to_string();
        if !is_forge_ident(&target) {
            return None;
        }
        let mut params = Vec::new();
        let mut numeric_args = Vec::new();
        for token in tokens {
            if let Ok(value) = token.parse::<f64>() {
                numeric_args.push(value);
            } else if is_forge_ident(token) {
                params.push(token.to_string());
            } else {
                return None;
            }
        }
        let spec = Self {
            name: name.to_string(),
            kind,
            target,
            params,
            numeric_args,
            tolerance,
        };
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        let (named, numeric) = self.kind.signature();
        self.params.len() == named
            && self.numeric_args.len() == numeric
            && self.numeric_args.iter().all(|value| value.is_finite())
            && self.tolerance.is_finite()
            && self.tolerance >= 0.0
            && !has_duplicates(&self.params.iter().map(String::as_str).collect::<Vec<_>>())
            && (self.kind != ForgePropertyKind::Range
                || self.numeric_args[0] <= self.numeric_args[1])
    }

    pub fn canonical_source(&self) -> String {
        let mut args = vec![self.target.clone()];
        args.extend(self.params.iter().cloned());
        args.extend(self.numeric_args.iter().map(|value| value.to_string()));
        format!(
            "property {}: {}({}) tolerance {}",
            self.name,
            self.kind.name(),
            args.join(","),
            self.tolerance
        )
    }

    pub fn property_hash_hex(&self) -> String {
        hash_text_hex("forge.source.property.v1", &self.canonical_source())
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ForgeValidationSpec {
    pub name: String,
    pub role: String,
    pub method: String,
    pub oracle: String,
    pub uncertainty: String,
    pub reference: String,
    pub replay: String,
    pub promotion: String,
    pub rollback: String,
}

impl ForgeValidationSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("validation ")?;
        let (name, body) = rest.split_once(':')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let mut role = None;
        let mut method = None;
        let mut oracle = None;
        let mut uncertainty = None;
        let mut reference = None;
        let mut replay = None;
        let mut promotion = None;
        let mut rollback = None;
        for item in body.split_whitespace() {
            let (key, value) = item.split_once('=')?;
            if !valid_forge_validation_token(value) {
                return None;
            }
            match key {
                "role" => role = Some(value.to_string()),
                "method" => method = Some(value.to_string()),
                "oracle" => oracle = Some(value.to_string()),
                "uncertainty" => uncertainty = Some(value.to_string()),
                "reference" => reference = Some(value.to_string()),
                "replay" => replay = Some(value.to_string()),
                "promotion" => promotion = Some(value.to_string()),
                "rollback" => rollback = Some(value.to_string()),
                _ => return None,
            }
        }
        let spec = Self {
            name: name.to_string(),
            role: role?,
            method: method?,
            oracle: oracle?,
            uncertainty: uncertainty?,
            reference: reference?,
            replay: replay?,
            promotion: promotion?,
            rollback: rollback?,
        };
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        [
            &self.role,
            &self.method,
            &self.oracle,
            &self.uncertainty,
            &self.reference,
            &self.replay,
            &self.promotion,
            &self.rollback,
        ]
        .iter()
        .all(|value| valid_forge_validation_token(value))
    }

    pub fn canonical_source(&self) -> String {
        format!(
            "validation {}: role={} method={} oracle={} uncertainty={} reference={} replay={} promotion={} rollback={}",
            self.name,
            self.role,
            self.method,
            self.oracle,
            self.uncertainty,
            self.reference,
            self.replay,
            self.promotion,
            self.rollback
        )
    }

    pub fn validation_hash_hex(&self) -> String {
        hash_text_hex("forge.source.validation.v1", &self.canonical_source())
    }
}

fn valid_forge_validation_token(raw: &str) -> bool {
    !raw.is_empty()
        && raw.len() <= 128
        && raw.chars().all(|ch| {
            ch.is_ascii_alphanumeric()
                || matches!(ch, '_' | '-' | '.' | ':' | '/' | '@')
        })
}

