#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ForgeRuntimeSpec {
    pub lowering: ForgeLoweringTarget,
    pub cpu_simd: ForgeRuntimeMode,
    pub cuda: ForgeRuntimeMode,
    pub memory_layout: ForgeScheduleLayout,
    pub sparse_layout: ForgeSparseLayout,
}

impl Default for ForgeRuntimeSpec {
    fn default() -> Self {
        Self {
            lowering: ForgeLoweringTarget::WgslRhi,
            cpu_simd: ForgeRuntimeMode::Auto,
            cuda: ForgeRuntimeMode::Optional,
            memory_layout: ForgeScheduleLayout::Soa,
            sparse_layout: ForgeSparseLayout::PageTable,
        }
    }
}

impl ForgeRuntimeSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let mut spec = Self::default();
        for line in raw.lines().map(str::trim).filter(|line| !line.is_empty() && !line.starts_with('#')) {
            if line == "none" {
                continue;
            }
            let (key, value) = line.split_once('=')?;
            match key.trim() {
                "lowering" => spec.lowering = ForgeLoweringTarget::parse(value.trim())?,
                "cpu_simd" => spec.cpu_simd = ForgeRuntimeMode::parse(value.trim())?,
                "cuda" => spec.cuda = ForgeRuntimeMode::parse(value.trim())?,
                "memory_layout" => spec.memory_layout = ForgeScheduleLayout::parse(value.trim())?,
                "sparse_layout" => spec.sparse_layout = ForgeSparseLayout::parse(value.trim())?,
                _ => return None,
            }
        }
        spec.is_valid().then_some(spec)
    }

    pub fn is_valid(&self) -> bool {
        !(self.lowering == ForgeLoweringTarget::Cuda && self.cuda == ForgeRuntimeMode::Off)
            && !(self.lowering == ForgeLoweringTarget::CpuSimd && self.cpu_simd == ForgeRuntimeMode::Off)
    }

    pub fn canonical_source(&self) -> String {
        format!(
            "runtime lowering={} cpu_simd={} cuda={} memory_layout={} sparse_layout={}",
            self.lowering.name(),
            self.cpu_simd.name(),
            self.cuda.name(),
            self.memory_layout.name(),
            self.sparse_layout.name()
        )
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ForgeSealedHostcallSpec {
    pub name: String,
    pub hostcall: String,
    pub capability_hash: String,
}

impl ForgeSealedHostcallSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("hostcall ")?;
        let (name, rest) = rest.split_once(':')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let mut parts = rest.split_whitespace();
        if parts.next()? != "sealed" {
            return None;
        }
        let hostcall = parts.next()?.trim();
        if !is_allowed_source_hostcall(hostcall) {
            return None;
        }
        let capability = parts.next()?.strip_prefix("capability=")?;
        if parts.next().is_some() {
            return None;
        }
        Some(Self {
            name: name.to_string(),
            hostcall: hostcall.to_string(),
            capability_hash: normalize_forge_hash(capability)?,
        })
    }

    pub fn canonical_source(&self) -> String {
        format!(
            "hostcall {}: sealed {} capability={}",
            self.name, self.hostcall, self.capability_hash
        )
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ForgeImportSpec {
    pub name: String,
    pub hash: String,
    /// Optional `(major, minor)` Forge dialect version the imported
    /// content-addressed module was authored against. `None` means the import
    /// is dialect-agnostic and always accepted.
    pub dialect: Option<(u32, u32)>,
}

/// Current major version of the Forge source dialect. A breaking change to the
/// language surface bumps the major and refuses same-name lower-major imports,
/// the way semantic versioning and MLIR/Unison content-addressed code treat
/// incompatible revisions.
pub const FORGE_DIALECT_VERSION_MAJOR: u32 = 1;
/// Current minor version of the Forge source dialect. Minor bumps add words
/// without breaking older modules; the host accepts imports authored against
/// any minor `<=` this one within the same major.
pub const FORGE_DIALECT_VERSION_MINOR: u32 = 1;

/// Host Forge dialect version `(major, minor)`.
pub fn forge_dialect_version() -> (u32, u32) {
    (FORGE_DIALECT_VERSION_MAJOR, FORGE_DIALECT_VERSION_MINOR)
}

/// Stable content-address tag for the host Forge dialect version.
pub fn forge_dialect_tag() -> String {
    format!("forge.dialect.v{FORGE_DIALECT_VERSION_MAJOR}.{FORGE_DIALECT_VERSION_MINOR}")
}

fn parse_forge_dialect_version(raw: &str) -> Option<(u32, u32)> {
    let raw = raw.trim();
    match raw.split_once('.') {
        Some((major, minor)) => Some((major.trim().parse().ok()?, minor.trim().parse().ok()?)),
        None => Some((raw.parse().ok()?, 0)),
    }
}

impl ForgeImportSpec {
    pub fn parse(raw: &str) -> Option<Self> {
        let rest = raw.trim().strip_prefix("import hash ")?;
        let (name, value) = rest.split_once('=')?;
        let name = name.trim();
        if !is_forge_ident(name) {
            return None;
        }
        let value = value.trim();
        let (hash_part, dialect) = match value.split_once(" dialect ") {
            Some((hash, dialect)) => (hash.trim(), Some(parse_forge_dialect_version(dialect)?)),
            None => (value, None),
        };
        let hash = normalize_forge_hash(hash_part)?;
        Some(Self { name: name.to_string(), hash, dialect })
    }

    pub fn canonical_source(&self) -> String {
        match self.dialect {
            Some((major, minor)) => {
                format!("import hash {} = {} dialect {}.{}", self.name, self.hash, major, minor)
            }
            None => format!("import hash {} = {}", self.name, self.hash),
        }
    }

    /// A content-addressed import is compatible when it declares no dialect, or
    /// when it shares the host major version and was authored against a minor
    /// version the host already implements (`minor <= host_minor`). A newer
    /// minor could use words this host lacks; a different major is a breaking
    /// revision, so both are refused.
    pub fn dialect_is_compatible(&self, host_major: u32, host_minor: u32) -> bool {
        match self.dialect {
            None => true,
            Some((major, minor)) => major == host_major && minor <= host_minor,
        }
    }

    pub fn import_hash_hex(&self) -> String {
        hash_text_hex("forge.source.import.v1", &self.canonical_source())
    }
}

