#[derive(Clone, Debug, PartialEq)]
pub enum ForgeIrOp {
    Input { name: String },
    Constant { name: String, value: ForgeScalarValue },
    Literal(ForgeScalarValue),
    Unary(ForgeUnaryOp),
    Binary(ForgeBinaryOp),
    Call { name: String },
    Let { name: String },
    Emit { name: String, handoff: ForgeOutputKind },
    Constraint { name: String },
    Sample { name: String, seed: Option<u64> },
}

impl ForgeIrOp {
    fn label(&self) -> String {
        match self {
            Self::Input { name } => format!("input:{name}"),
            Self::Constant { name, value } => format!("const:{name}={value}"),
            Self::Literal(value) => format!("literal:{value}"),
            Self::Unary(op) => format!("unary:{op}"),
            Self::Binary(op) => format!("binary:{op}"),
            Self::Call { name } => format!("call:{name}"),
            Self::Let { name } => format!("let:{name}"),
            Self::Emit { name, handoff } => format!("emit:{name}:{handoff}"),
            Self::Constraint { name } => format!("constraint:{name}"),
            Self::Sample { name, seed } => format!("sample:{name}:{seed:?}"),
        }
    }
}

