#[test]
fn delta_kasm_updates_vsum_without_full_recompute_and_proves_replay() {
    let prog = Program::new(
        Target::Cpu, 1, 1, 3,
        vec![Node::input_vec(0), Node::v_sum(0), Node::output(1, Ty::I64)],
    ).unwrap();
    let old_vec = vec![10i64, 20, 30, 40, 50];
    let previous = 150i64.to_le_bytes();
    let patches = [
        KasmDeltaPatch { index: 1, old: 20, new: 25 },
        KasmDeltaPatch { index: 4, old: 50, new: 30 },
    ];

    let (out, proof) =
        execute_vec_sum_delta_checked(&prog, &old_vec, &previous, &patches).unwrap();

    let out_bytes: [u8; 8] = out.try_into().unwrap();
    assert_eq!(i64::from_le_bytes(out_bytes), 135);
    assert!(proof.full_replay_checked);
    assert_eq!(proof.patches, 2);
    assert_eq!(proof.saved_ops_estimate, 3);
    assert!(proof.full_replay_hash.is_some());
    assert_ne!(proof.delta_hash, proof.output_hash);
}

#[test]
fn delta_kasm_fast_path_is_order_stable_and_rejects_duplicate_patches() {
    let prog = Program::new(
        Target::Cpu, 1, 1, 3,
        vec![Node::input_vec(0), Node::v_sum(0), Node::output(1, Ty::I64)],
    ).unwrap();
    let state_hash = vec_i64_state_hash(&[1, 2, 3]);
    let previous = 6i64.to_le_bytes();
    let a = [
        KasmDeltaPatch { index: 2, old: 3, new: 9 },
        KasmDeltaPatch { index: 0, old: 1, new: -1 },
    ];
    let b = [a[1], a[0]];

    let (out_a, proof_a) = execute_vec_sum_delta(&prog, &state_hash, &previous, &a).unwrap();
    let (out_b, proof_b) = execute_vec_sum_delta(&prog, &state_hash, &previous, &b).unwrap();
    assert_eq!(out_a, out_b);
    assert_eq!(proof_a.delta_hash, proof_b.delta_hash);
    assert_eq!(proof_a.proof_hash, proof_b.proof_hash);

    let duplicate = [a[0], a[0]];
    assert!(matches!(
        execute_vec_sum_delta(&prog, &state_hash, &previous, &duplicate),
        Err(KasmDeltaError::BadPatch(_))
    ));
}

