impl Default for ForgeVmConfig {
    fn default() -> Self {
        Self {
            max_fuel: 128,
            max_memory_bytes: 64 * 1024,
            max_input_bytes: 64 * 1024,
            max_output_bytes: 64 * 1024,
            backend: "fbc_interpreter".to_string(),
            forbidden_opcodes: Vec::new(),
        }
    }
}

impl ForgeBytecodeProgram {
    pub fn v0(name: impl Into<String>, ops: Vec<ForgeOpcode>) -> Self {
        let mut hostcalls = Vec::new();
        for op in &ops {
            for call in required_hostcalls(op) {
                if !hostcalls.contains(&call) {
                    hostcalls.push(call);
                }
            }
        }
        Self {
            name: name.into(),
            version: FBC_VERSION,
            capabilities: Vec::new(),
            hostcalls,
            ops,
            expected_output_schema: "bytes".to_string(),
            deterministic: true,
        }
    }

    pub fn with_capability(mut self, capability: ForgeCapability) -> Self {
        self.capabilities.push(capability);
        self
    }

    pub fn with_hostcall(mut self, hostcall: ForgeHostCall) -> Self {
        if !self.hostcalls.contains(&hostcall) {
            self.hostcalls.push(hostcall);
        }
        self
    }
}

impl ForgeHostContext {
    pub fn with_binding(mut self, capability: &ForgeCapability, bytes: Vec<u8>) -> Self {
        self.bindings.push(ForgeCapabilityBinding {
            sealed_hash: capability.sealed_hash,
            bytes,
        });
        self
    }

    fn read_binding(&self, sealed_hash: &[u8; 32]) -> Option<&[u8]> {
        self.bindings
            .iter()
            .find(|binding| &binding.sealed_hash == sealed_hash)
            .map(|binding| binding.bytes.as_slice())
    }
}

impl ForgeCapability {
    pub fn sealed(
        kind: ForgeCapabilityKind,
        scope: impl AsRef<str>,
        content: Option<&[u8]>,
        limit_bytes: u64,
    ) -> Self {
        let scope = scope.as_ref().to_string();
        let content_hash = content.map(sha256);
        let mut h = Sha256::new();
        h.update(b"forge-fbc-capability-v0\n");
        write_cap_kind(&mut h, kind);
        h.update(b"\n");
        h.update(scope.as_bytes());
        h.update(b"\n");
        h.update(limit_bytes.to_le_bytes());
        if let Some(content_hash) = content_hash {
            h.update(content_hash);
        }
        Self {
            kind,
            scope,
            sealed_hash: h.finalize().into(),
            content_hash,
            limit_bytes,
        }
    }

    pub fn artifact_handle(
        scope: impl AsRef<str>,
        content: Option<&[u8]>,
        limit_bytes: u64,
    ) -> Result<Self, String> {
        let scope = bounded_capability_scope(ForgeCapabilityKind::ArtifactHash, scope.as_ref())?;
        Ok(Self::sealed(
            ForgeCapabilityKind::ArtifactHash,
            scope,
            content,
            limit_bytes,
        ))
    }

    pub fn memory_scope_handle(
        scope: impl AsRef<str>,
        content: Option<&[u8]>,
        limit_bytes: u64,
    ) -> Result<Self, String> {
        let scope = bounded_capability_scope(ForgeCapabilityKind::MemoryScope, scope.as_ref())?;
        Ok(Self::sealed(
            ForgeCapabilityKind::MemoryScope,
            scope,
            content,
            limit_bytes,
        ))
    }

    pub fn ui_projection_handle(
        scope: impl AsRef<str>,
        content: Option<&[u8]>,
        limit_bytes: u64,
    ) -> Result<Self, String> {
        let scope = bounded_capability_scope(ForgeCapabilityKind::UiProjection, scope.as_ref())?;
        Ok(Self::sealed(
            ForgeCapabilityKind::UiProjection,
            scope,
            content,
            limit_bytes,
        ))
    }

    pub fn model_provider_scope_handle(
        scope: impl AsRef<str>,
        content: Option<&[u8]>,
        limit_bytes: u64,
    ) -> Result<Self, String> {
        let scope =
            bounded_capability_scope(ForgeCapabilityKind::ModelProviderScope, scope.as_ref())?;
        Ok(Self::sealed(
            ForgeCapabilityKind::ModelProviderScope,
            scope,
            content,
            limit_bytes,
        ))
    }

    pub fn summary(&self) -> String {
        format!(
            "cap:{}:{}:{}:{}",
            cap_kind_name(self.kind),
            self.scope,
            hex(&self.sealed_hash),
            self.limit_bytes
        )
    }
}

fn bounded_capability_scope(kind: ForgeCapabilityKind, scope: &str) -> Result<String, String> {
    let trimmed = scope.trim();
    if trimmed.is_empty() {
        return Err("capability scope must not be empty".to_string());
    }
    if trimmed.contains('\\')
        || trimmed.starts_with('/')
        || trimmed.contains("../")
        || trimmed.contains("..\\")
        || trimmed.contains(":/")
        || trimmed.contains(":\\")
    {
        return Err(format!(
            "{} handle must not contain raw path syntax: {}",
            cap_kind_name(kind),
            scope
        ));
    }
    let lower = trimmed.to_ascii_lowercase();
    if lower.contains("http://")
        || lower.contains("https://")
        || lower.contains("ws://")
        || lower.contains("wss://")
    {
        return Err(format!(
            "{} handle must not contain a raw URL: {}",
            cap_kind_name(kind),
            scope
        ));
    }
    if lower.contains("token")
        || lower.contains("bearer ")
        || lower.contains("api_key")
        || lower.contains("apikey")
        || lower.contains("secret")
        || trimmed.starts_with("sk-")
    {
        return Err(format!(
            "{} handle must not embed a token or secret: {}",
            cap_kind_name(kind),
            scope
        ));
    }
    if !trimmed
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, ':' | '_' | '-' | '.'))
    {
        return Err(format!(
            "{} handle contains unsupported characters: {}",
            cap_kind_name(kind),
            scope
        ));
    }
    Ok(trimmed.to_string())
}

